#!/usr/bin/env node

import { readFileSync } from "node:fs";
import { verifyDeployment } from "./lib/release-integrity.mjs";

function argument(name) {
  const index = process.argv.indexOf(name);
  return index >= 0 ? process.argv[index + 1] : undefined;
}

function positiveInteger(value, fallback) {
  const parsed = Number.parseInt(String(value ?? ""), 10);
  return Number.isFinite(parsed) && parsed >= 0 ? parsed : fallback;
}

const manifest = JSON.parse(
  readFileSync(new URL("../release/source-manifest.json", import.meta.url), "utf8"),
);
const origin = argument("--url") || process.env.PRODUCTION_URL;
const expectedSha = argument("--expected-sha") || process.env.EXPECTED_SHA || process.env.GITHUB_SHA;
const expectedSourceHash =
  argument("--expected-source-hash") ||
  process.env.EXPECTED_SOURCE_HASH ||
  manifest.sourceHash;
const attempts = positiveInteger(argument("--attempts") || process.env.VERIFY_ATTEMPTS, 1);
const delayMs = positiveInteger(argument("--delay-ms") || process.env.VERIFY_DELAY_MS, 0);

if (!origin) {
  console.error("Production verification requires --url or PRODUCTION_URL.");
  process.exit(2);
}
if (!expectedSha) {
  console.error("Production verification requires --expected-sha, EXPECTED_SHA, or GITHUB_SHA.");
  process.exit(2);
}
if (!expectedSourceHash) {
  console.error("Production verification requires a certified source hash.");
  process.exit(2);
}

const report = await verifyDeployment({
  origin,
  expectedSha,
  expectedSourceHash,
  attempts,
  delayMs,
});
console.log(JSON.stringify(report, null, 2));

if (!report?.ok) {
  console.error("Production source-integrity/readiness verification failed.");
  process.exit(1);
}

import { z } from "zod";
import { sanitizeText, scanText } from "@/lib/provenance/unicode";
import { ApiRequestError, apiError, apiOk, parseJson, requestContext } from "@/lib/server/api";
import { logEvent } from "@/lib/server/observability";
import { trackInspectionCompleted } from "@/lib/server/pulseatlas";

const bodySchema = z.object({ text: z.string().max(250_000), sanitize: z.enum(["none", "conservative", "aggressive"]).default("none") });
export async function POST(request: Request) {
  const context = requestContext(request, "/api/scan");
  try {
    const parsed = await parseJson(request, bodySchema, 300_000);
    const receipt = scanText(parsed.text);
    const sanitation = parsed.sanitize === "none" ? null : sanitizeText(parsed.text, parsed.sanitize);
    logEvent("scan_request", { requestId: context.requestId, sourceChars: parsed.text.length, findings: receipt.summary.total, sanitizeMode: parsed.sanitize });
    // Content-blind and fail-open: raw text, receipts, and sanitation output never leave this boundary.
    void trackInspectionCompleted({ fileType: "text", operation: parsed.sanitize === "none" ? "inspect" : "inspect_and_sanitize", result: "success" });
    return apiOk(context, { receipt, sanitation });
  } catch (error) {
    if (error instanceof ApiRequestError) return apiError(context, error.code, error.message, error.status);
    return apiError(context, "scan_failed", "The scan could not be completed.", 500);
  }
}

import { latin1 } from "./binary";
import type { FileFinding } from "./types";

export function inspectPdf(bytes: Uint8Array): FileFinding[] {
  const text = latin1(bytes);
  const findings: FileFinding[] = [];
  const add = (id: string, kind: FileFinding["kind"], label: string, description: string, disposition: FileFinding["disposition"] = "privacy_metadata") => {
    findings.push({ id, kind, label, description, disposition, removableByDefault: false });
  };

  const infoKeys = ["Author", "Creator", "Producer", "CreationDate", "ModDate", "Title", "Subject", "Keywords"];
  const present = infoKeys.filter((key) => new RegExp(`\\/${key}\\s*(?:\\(|<)`, "m").test(text));
  if (present.length) add("pdf-info", "pdf_info", "PDF document information", `Document Info fields detected: ${present.join(", ")}. PDF rewriting is inspection-only in this phase to avoid corrupting signed or structurally complex files.`);

  if (/<x:xmpmeta\b|<rdf:RDF\b|adobe:ns:meta\//i.test(text)) {
    add("pdf-xmp", "pdf_xmp", "PDF XMP packet", "Embedded XMP metadata detected. Inspection-only until the PDF rewrite path can preserve cross-reference integrity.");
  }

  if (/c2pa|jumbf|contentauth|content credentials/i.test(text)) {
    add("pdf-provenance", "provenance_manifest", "Potential provenance manifest", "Potential signed provenance markers detected. These are never removed by default.", "provenance");
  }

  return findings;
}

import { timingSafeEqual } from "node:crypto";
import { rollupDailyMetrics } from "@/lib/billing/server";
import { apiError, apiOk, requestContext } from "@/lib/server/api";
export const runtime="nodejs";
function authorized(request:Request){const secret=process.env.CRON_SECRET??"";const supplied=request.headers.get("authorization")?.replace(/^Bearer\s+/iu,"")??"";const a=Buffer.from(secret);const b=Buffer.from(supplied);return Boolean(secret&&supplied&&a.length===b.length&&timingSafeEqual(a,b));}
export async function GET(request:Request){const context=requestContext(request,"/api/internal/ops-rollup");if(!authorized(request))return apiError(context,"unauthorized","Not authorized.",401);try{const date=new Date(Date.now()-86_400_000).toISOString().slice(0,10);const result=await rollupDailyMetrics(date,context.requestId);return apiOk(context,{rolledUp:true,date,result});}catch{return apiError(context,"rollup_failed","Daily operations rollup failed.",503);}}

